package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.world.item.*;import net.minecraft.world.*;import net.minecraft.world.level.Level;import net.minecraft.world.entity.player.Player;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.phys.*;import net.minecraft.network.chat.Component;
/** One validated server transaction for new and packed submarines. */
public final class Sd01Item extends Item {
 public Sd01Item(Properties p){super(p);}
 @Override public InteractionResult useOn(net.minecraft.world.item.context.UseOnContext c){return c.getPlayer()==null?InteractionResult.PASS:use(c.getLevel(),c.getPlayer(),c.getHand()).getResult();}
 @Override public InteractionResultHolder<ItemStack> use(Level l,Player p,InteractionHand h){var stack=p.getItemInHand(h);if(l.isClientSide)return InteractionResultHolder.success(stack);if(!(p instanceof ServerPlayer sp)||!p.isAlive()||p.isSpectator()||!p.mayBuild())return InteractionResultHolder.fail(stack);var hit=getPlayerPOVHitResult(l,p,net.minecraft.world.level.ClipContext.Fluid.SOURCE_ONLY);if(hit.getType()!=HitResult.Type.BLOCK)return fail(p,stack);Vec3 at=p.isUnderWater()?p.getEyePosition().add(p.getLookAngle().scale(4.5)):hit.getLocation().add(0,-1.25,0);return deploy(l,sp,h,at,p.getYRot());}
 public static InteractionResultHolder<ItemStack> deploy(Level l,ServerPlayer p,InteractionHand h,Vec3 at,float yaw){var stack=p.getItemInHand(h);if(l.isClientSide||!(stack.is(AddonItems.SD01.get())||ServiceContainers.is(stack,"submarine_drone_sd01"))||!p.isAlive()||p.isSpectator()||!p.mayBuild()||p.position().distanceToSqr(at)>64)return InteractionResultHolder.fail(stack);var d=AddonEntities.SD01.get().create(l);if(d==null)return fail(p,stack);var saved=Gad01Item.saved(stack);if(saved!=null){var n=saved.copy();for(String k:new String[]{"UUID","Pos","Motion","Rotation","Passengers"})n.remove(k);d.load(n);}else d.setEnergy(d.getMaxEnergy());d.moveTo(at.x,at.y,at.z,yaw,0);d.yRotO=yaw;d.xRotO=0;d.setZRot(0);d.setDeltaMovement(Vec3.ZERO);d.releaseControl();if(!d.permitted(p)||!Sd01Hull.deployable(d,p,stack))return fail(p,stack);d.claimOwner(p);SbwCompat.ensureDroneOwner(d,p);d.updateOBB();if(!l.addFreshEntity(d))return fail(p,stack);if(!p.getAbilities().instabuild)stack.shrink(1);return InteractionResultHolder.consume(stack);}
 private static InteractionResultHolder<ItemStack> fail(Player p,ItemStack s){p.displayClientMessage(Component.translatable("sd01.placement"),true);return InteractionResultHolder.fail(s);}
 @Override public void initializeClient(java.util.function.Consumer<net.neoforged.neoforge.client.extensions.common.IClientItemExtensions> c){c.accept(new net.neoforged.neoforge.client.extensions.common.IClientItemExtensions(){public net.minecraft.client.renderer.BlockEntityWithoutLevelRenderer getCustomRenderer(){return Sd01ItemRenderer.instance();}});}
}
